package io.github.jesterportfolio.hearth.survival.economy;

import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.inventory.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.survival.*;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
import org.postgresql.ds.PGSimpleDataSource;
import net.kyori.adventure.text.Component;

/** 일반 생존의 경제 연결. 계산/PG 원자 거래는 기존 엔진을 그대로 사용합니다. */
public final class SurvivalEconomy implements AutoCloseable {
    public interface Boundary{Object token(Player p);boolean current(Player p,Object token);boolean available(Player p);void freeze(Player p,Object token,boolean value);void hold();Map<SurvivalWorld,World> worlds();Location spawn();}
    public enum Phase{STARTING,READY,DRAINING,DRAINED,HOLD,CLOSED}
    private io.github.jesterportfolio.hearth.survival.market.MarketRuntime market;
    public io.github.jesterportfolio.hearth.survival.market.MarketRuntime market(){return Objects.requireNonNull(market);}
    private record Session(Player player,Object token,ServerProgressAccess.Context context,AtomicBoolean alive){}
    public final NativeEconomySettings settings;public final EconomyContent content;public final Properties properties;public final EconomyStore store;public final EconomyTrade items;public final NativeEconomyLedger ledger;public final NativeTradeJournal journal;public final NativeTransactions transactions;public final EconomyMerchants merchants;public final SpawnShops shops;public final Executor owner;
    private final JavaPlugin plugin;private final Boundary boundary;private final PaperInventoryCodec codec=new PaperInventoryCodec();private final PostgresProgressStore database;private final Map<UUID,Session> sessions=new HashMap<>();private final Set<UUID> admissions=new HashSet<>();private final RuntimeLease.Lease lease;private final Path binding;private final UUID group;private final BukkitTask pulse;private final CompletableFuture<Void> ready=new CompletableFuture<>();private CompletionStage<Void> tickWork=CompletableFuture.completedFuture(null);private long nextTick,tick;private boolean ticking,closed;private volatile Phase phase=Phase.STARTING;public final NativeEconomyMenu menu;public final NativePeerMenu peers;
    public SurvivalEconomy(JavaPlugin plugin,UUID group,Boundary boundary)throws Exception{
        this.plugin=plugin;this.group=group;this.boundary=boundary;owner=action->Bukkit.getScheduler().runTask(plugin,action);
        settings=NativeEconomySettings.parse(Objects.requireNonNull(plugin.getConfig().getConfigurationSection("survival-economy")).getValues(false));var data=plugin.getDataFolder().toPath().toAbsolutePath();if(!data.equals(data.toRealPath()))throw new IllegalStateException("NATIVE_ECONOMY_PATH");binding=data.resolve("native-economy.properties");var file=data.resolve(settings.contentFile());if(!file.equals(file.toRealPath())||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>1024*1024)throw new IllegalStateException("NATIVE_ECONOMY_CONTENT");properties=new Properties();try(var r=Files.newBufferedReader(file)){properties.load(r);}content=EconomyContent.parse(properties);if(!content.offline().equals("PAUSE")||content.fixtureBalance()!=0)throw new IllegalStateException("NATIVE_ECONOMY_POLICY");merchants=EconomyMerchants.parse(properties,content);shops=SpawnShops.parse(properties,content,merchants);
        var source=new PGSimpleDataSource();source.setServerNames(new String[]{settings.host()});source.setPortNumbers(new int[]{settings.port()});source.setDatabaseName(settings.database());source.setUser(settings.user());String password=System.getenv(settings.passwordEnvironment());if(password==null)throw new IllegalStateException("NATIVE_ECONOMY_PASSWORD_ENV");source.setPassword(password);source.setConnectTimeout(2);source.setSocketTimeout(5);source.setPrepareThreshold(0);
        journal=new NativeTradeJournal(data,group);lease=RuntimeLease.acquire(data.resolve("native-economy.active"),"Hearth native economy v1\n"+group+"\n").orElseThrow(()->new IllegalStateException("NATIVE_ECONOMY_UNCLEAN_HOLD"));database=PostgresProgressStore.forModules(source,f->plugin.getLogger().warning("HEARTH_NATIVE_ECONOMY_DB_ERROR code="+f.code()));store=new EconomyStore(database,content);items=new EconomyTrade(store,codec,owner);ledger=new NativeEconomyLedger(store,items);transactions=new NativeTransactions(journal,owner,System::currentTimeMillis);menu=new NativeEconomyMenu(plugin,this);peers=new NativePeerMenu(plugin,this);pulse=Bukkit.getScheduler().runTaskTimer(plugin,this::tick,1,1);
        try{String worlds=worldsHash(boundary.worlds());boolean existing=Files.exists(binding,LinkOption.NOFOLLOW_LINKS);if(existing)checkBinding(worlds);store.migrate().thenCompose(v->store.openNativeRealm(settings.realm(),group,worlds,System.currentTimeMillis(),!existing&&settings.allowNew())).thenCompose(v->store.resumeClock(settings.realm(),System.currentTimeMillis())).thenComposeAsync(v->{if(!plugin.getConfig().getBoolean("market-automation.enabled"))return store.requireUnmanaged(settings.realm());var controls=io.github.jesterportfolio.hearth.survival.market.MarketSettings.parse(Objects.requireNonNull(plugin.getConfig().getConfigurationSection("market-automation")).getValues(false));market=new io.github.jesterportfolio.hearth.survival.market.MarketRuntime(store,settings.realm(),data,controls,owner,()->phase==Phase.READY&&!closed);return market.open();},owner).thenCompose(v->store.snapshot(settings.realm())).thenComposeAsync(state->{tick=state.tick();if(!existing)writeBinding(worlds);return menu.prepare();},owner).whenCompleteAsync((v,error)->{if(closed)return;if(error!=null){hold("STARTUP_FAILED");ready.completeExceptionally(error);}else{phase=Phase.READY;nextTick=System.currentTimeMillis()+content.tickMillis();ready.complete(null);plugin.getLogger().info("HEARTH_SURVIVAL_ECONOMY_READY native=true currency=PG offline=PAUSE");}},owner);}catch(Exception error){hold("STARTUP_FAILED");ready.completeExceptionally(error);}
    }
    public static String worldsHash(Map<SurvivalWorld,World> worlds)throws Exception{var text=new StringBuilder();for(var role:SurvivalWorld.values()){var w=Objects.requireNonNull(worlds.get(role));text.append(role.id()).append(':').append(w.getKey()).append(':').append(w.getUID()).append('\n');}return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
    private void checkBinding(String worlds)throws Exception{if(!binding.equals(binding.toRealPath())||!Files.isRegularFile(binding,LinkOption.NOFOLLOW_LINKS)||Files.size(binding)>4096)throw new IllegalStateException("NATIVE_ECONOMY_BINDING");var p=new Properties();try(var r=Files.newBufferedReader(binding)){p.load(r);}if(!settings.realm().toString().equals(p.getProperty("realm"))||!group.toString().equals(p.getProperty("group"))||!worlds.equals(p.getProperty("worlds"))||!content.fingerprint().equals(p.getProperty("content")))throw new IllegalStateException("NATIVE_ECONOMY_BINDING");}
    private void writeBinding(String worlds){try{var p=new Properties();p.setProperty("realm",settings.realm().toString());p.setProperty("group",group.toString());p.setProperty("worlds",worlds);p.setProperty("content",content.fingerprint());try(var out=Files.newBufferedWriter(binding,StandardOpenOption.CREATE_NEW)){p.store(out,"Hearth native economy binding v1");}try(var channel=java.nio.channels.FileChannel.open(binding,StandardOpenOption.WRITE)){channel.force(true);}}catch(Exception error){throw new IllegalStateException("NATIVE_ECONOMY_BINDING");}}
    public boolean aiPreparationRecorded(){return market!=null&&market.director().preparationRecorded();}
    public CompletionStage<Void> ready(){return ready;}public Phase phase(){return phase;}
    public boolean admitted(Player p){var s=sessions.get(p.getUniqueId());return phase==Phase.READY&&s!=null&&s.player()==p&&s.alive().get()&&boundary.current(p,s.token())&&!p.isDead();}
    public boolean free(Player p){return admitted(p)&&boundary.available(p)&&!transactions.busy(p.getUniqueId());}
    public boolean busy(Player p){return admissions.contains(p.getUniqueId())||!admitted(p)||transactions.busy(p.getUniqueId())||peers.busy(p.getUniqueId());}
    public Object token(Player p){return admitted(p)?sessions.get(p.getUniqueId()).token():null;}
    public boolean same(Player p,Object token){return admitted(p)&&sessions.get(p.getUniqueId()).token()==token;}
    public ServerProgressAccess.Context context(Player p){if(!admitted(p))throw new IllegalStateException("NATIVE_ECONOMY_SESSION");return sessions.get(p.getUniqueId()).context();}
    public void admit(Player p){if(phase!=Phase.READY||p.isDead()||!boundary.available(p)||journal.held(p.getUniqueId())){p.kick(Component.text("경제 거래 보류 기록이 있습니다. 관리자 확인이 필요합니다."));return;}var token=boundary.token(p);var session=new Session(p,token,store.context(settings.realm(),p.getUniqueId()),new AtomicBoolean(true));if(token==null||admissions.contains(p.getUniqueId())||sessions.containsKey(p.getUniqueId())){p.kick(Component.text("경제 계정 준비 상태를 확인하세요."));return;}sessions.put(p.getUniqueId(),session);admissions.add(p.getUniqueId());boundary.freeze(p,token,true);store.ensureAccount(session.context(),codec.encode(new org.bukkit.inventory.ItemStack[41])).whenCompleteAsync((account,error)->{if(sessions.get(p.getUniqueId())!=session||!session.alive().get()||!boundary.current(p,token))return;admissions.remove(p.getUniqueId());if(error!=null){session.alive().set(false);p.kick(Component.text("경제 계정 확인 실패 · 원본 소지품을 보존했습니다."));}else boundary.freeze(p,token,false);},owner);}
    public void invalidate(Player p){var s=sessions.get(p.getUniqueId());if(s==null||s.player()!=p)return;s.alive().set(false);sessions.remove(p.getUniqueId(),s);admissions.remove(p.getUniqueId());menu.invalidate(p.getUniqueId());transactions.invalidate(p.getUniqueId());peers.invalidate(p.getUniqueId());}
    public NativeTransactions.Port port(Player p){var session=Objects.requireNonNull(sessions.get(p.getUniqueId()));var world=p.getWorld();return new NativeTransactions.Port(){public UUID player(){return p.getUniqueId();}public boolean current(){return !closed&&phase==Phase.READY&&session.alive().get()&&sessions.get(p.getUniqueId())==session&&boundary.current(p,session.token())&&!p.isDead()&&p.getWorld()==world;}public InventoryPayload capture(){if(!p.getItemOnCursor().isEmpty())throw new IllegalStateException("NATIVE_TRADE_CURSOR");return codec.capture(p.getInventory());}public boolean same(InventoryPayload before){return current()&&p.getItemOnCursor().isEmpty()&&codec.equivalent(before,codec.capture(p.getInventory()));}public void freeze(boolean value){boundary.freeze(p,session.token(),value);}public void saveNative(){if(!current())throw new IllegalStateException("NATIVE_TRADE_STALE");VanillaPlayerFiles.save(Bukkit.getServer().getLevelDirectory(),p.getUniqueId(),p::saveData);}public void validate(InventoryPayload after){codec.decode(after);}public void apply(InventoryPayload after){codec.apply(p.getInventory(),after);}public void notice(String code){if(current())p.sendMessage(Component.text(code.equals("NATIVE_TRADE_COMPLETE")?"거래 완료 · 소지품과 잔액을 저장했습니다.":"거래 결과 보류 · 재요청하지 말고 관리자에게 알려주세요. "+code));}};}
    public InventoryPayload capture(Player p){return codec.capture(p.getInventory());}
    public PostgresProgressStore database(){return database;}
    public Location spawn(){return boundary.spawn().clone();}
    public World world(SurvivalWorld role){return Objects.requireNonNull(boundary.worlds().get(role));}
    private void tick(){if(closed)return;transactions.tick();peers.tick();if(phase==Phase.READY&&!ticking&&System.currentTimeMillis()>=nextTick)advanceTick();}
    /** 같은 스케줄러 경계의 단일 Tick. 격리 검증도 이 경로를 사용합니다. */
    public CompletionStage<Void> advanceTick(){if(phase!=Phase.READY||ticking)return CompletableFuture.failedFuture(new IllegalStateException("NATIVE_ECONOMY_TICK_BUSY"));ticking=true;tickWork=(market==null?store.tick(settings.realm(),tick,System.currentTimeMillis()):market.tick(tick,System.currentTimeMillis())).thenAcceptAsync(done->{if(!done)throw new IllegalStateException("NATIVE_ECONOMY_TICK_CONFLICT");tick++;ticking=false;nextTick=System.currentTimeMillis()+content.tickMillis();},owner);tickWork.whenCompleteAsync((v,error)->{ticking=false;if(error!=null)hold("TICK_FAILED");},owner);return tickWork;}
    private void hold(String code){phase=Phase.HOLD;boundary.hold();for(var p:Bukkit.getOnlinePlayers())p.sendMessage(Component.text("경제 처리를 보류했습니다. 재요청하지 말고 관리자 확인을 기다려 주세요."));plugin.getLogger().warning("HEARTH_SURVIVAL_ECONOMY_HOLD code="+code);}
    public CompletionStage<Void> drain(){if(phase==Phase.DRAINED)return CompletableFuture.completedFuture(null);if(phase!=Phase.READY||!transactions.settled())return CompletableFuture.failedFuture(new IllegalStateException("NATIVE_ECONOMY_DRAIN_BUSY"));phase=Phase.DRAINING;if(market!=null)market.close();for(var p:List.copyOf(Bukkit.getOnlinePlayers()))p.kick(Component.text("경제 서버 저장·종료 준비 중"));return tickWork.thenCompose(v->database.closeAsync()).thenRunAsync(()->{try{lease.clean();phase=Phase.DRAINED;plugin.getLogger().info("HEARTH_SURVIVAL_ECONOMY_DRAINED PASS");}catch(Exception failure){hold("DRAIN_MARKER_FAILED");throw new IllegalStateException(failure);}},owner);}
    public void console(String[] args,java.util.function.Consumer<String> out){try{
        if(args.length==2&&args[0].equals("market-verify")){io.github.jesterportfolio.hearth.verification.MarketVerification.run(plugin,this,database,args[1]).whenCompleteAsync((v,error)->plugin.getLogger().log(error==null?java.util.logging.Level.INFO:java.util.logging.Level.SEVERE,"HEARTH_MARKET_PROBE "+(error==null?"PASS ":"FAIL ")+args[1],error),owner);return;}
        if(args.length>0&&args[0].equals("automation")){if(market==null)out.accept("시장 자동 운영이 설정되지 않았습니다.");else market.console(Arrays.copyOfRange(args,1,args.length),out);return;}
        if(args.length==2&&args[0].equals("native-verify")){io.github.jesterportfolio.hearth.verification.NativeEconomyVerification.run(plugin,this,database,args[1]).whenCompleteAsync((v,error)->plugin.getLogger().log(error==null?java.util.logging.Level.INFO:java.util.logging.Level.SEVERE,"HEARTH_NATIVE_ECONOMY_PROBE "+(error==null?"PASS ":"FAIL ")+args[1],error),owner);return;}
        if(Arrays.equals(args,new String[]{"status"})){out.accept("생존 경제="+phase+" 보류="+journal.pending().size());return;}
        if(Arrays.equals(args,new String[]{"pending"})){out.accept("생존 경제 보류 기록="+journal.pending());return;}
        if(args.length==2&&args[0].equals("inspect")){var request=UUID.fromString(args[1]);var p=journal.pending().stream().filter(row->row.request().equals(request)).findFirst().orElseThrow();var context=store.context(settings.realm(),p.players().getFirst());CompletionStage<?> work=p.kind().equals("SHOP")?store.receipt(context,request):store.peerReceipt(context,request);work.whenCompleteAsync((row,error)->out.accept(error==null?"확정 영수증 조회="+row+" · 자동 재지급/표식 삭제 없음":"영수증 조회 실패 · 원본 보존"),owner);return;}
        if(args.length==3&&args[0].equals("event")&&phase==Phase.READY){store.event(settings.realm(),UUID.fromString(args[1]),args[2]).whenCompleteAsync((v,error)->out.accept(error==null?"등록 경제 사건을 예약했습니다.":"경제 사건 예약 실패"),owner);return;}
        out.accept("heartheconomy status|pending|inspect <요청 UUID>|event <요청 UUID> <등록 사건> · 종료는 hearthsurvivaladmin drain");
    }catch(RuntimeException invalid){out.accept("경제 관리 인자/보류 기록을 확인하세요.");}}
    @Override public void close(){if(closed)return;boolean clean=phase==Phase.DRAINED;closed=true;phase=Phase.CLOSED;pulse.cancel();if(market!=null)market.close();transactions.close();peers.close();menu.close();for(var s:sessions.values())s.alive().set(false);database.closeAsync();plugin.getLogger().info("HEARTH_SURVIVAL_ECONOMY_CLOSE "+(clean?"PASS":"HOLD"));}
}
